def web_shot(lang='de'):
    W=WEBSHOT[lang]; t0=W['tabs'][0]; src=lambda k:'/assets/app/'+k+'-de.webp'
    btns=''.join('<button data-web="'+src(k)+'" data-alt="'+alt+'" data-text="'+txt+'" aria-pressed="'+('true' if i==0 else 'false')+'">'+lab+'</button>' for i,(k,lab,alt,txt) in enumerate(W['tabs']))
    return '<figure class="web-shot"><div class="browser-bar" aria-hidden="true"><i></i><i></i><i></i><span>plan.onpath.earth</span></div><img id="web-img" src="'+src(t0[0])+'" alt="'+t0[2]+'" width="1440" height="900" loading="lazy"><figcaption><div class="web-tabs" role="group" aria-label="'+W['ctl']+'">'+btns+'</div><span id="web-text" aria-live="polite">'+t0[3]+'</span></figcaption></figure>'
def ways_section(lang='de'):
    W=WAYS[lang]; T=WEBSHOT[lang]['tabs']
    ways=''.join('<div class="way-lite">'+icon(ic)+'<div><h3>'+t+'</h3><ul>'+''.join('<li>'+x+'</li>' for x in li)+'</ul></div></div>' for ic,t,li in W['cards'])
    phone_alt='OnPath auf dem Handy: dieselbe Wanderung, bereit zum Losgehen' if lang=='de' else 'OnPath on the phone: the same hike, ready to go'
    duo='<figure class="duo"><div class="duo-browser"><div class="browser-bar" aria-hidden="true"><i></i><i></i><i></i><span>plan.onpath.earth</span></div><img src="/assets/app/web-wandern-de.webp" alt="'+T[0][2]+'" width="1440" height="900" loading="lazy"></div><img class="duo-phone" src="/assets/app/plan-wandern-'+lang+'.webp" alt="'+phone_alt+'" width="600" height="1333" loading="lazy"></figure>'
    return '<section class="section" id="'+('planen' if lang=='de' else 'plan')+'"><div class="wrap split ways-split"><div><p class="eyebrow">'+W['eye']+'</p><h2>'+W['h']+'</h2><p class="ways-lead">'+W['lead']+'</p>'+ways+'<div class="ways-cta"><a class="button" href="https://plan.onpath.earth/">'+W['open']+icon('arrow')+'</a><span class="ways-note">'+W['note']+'</span></div></div>'+duo+'</div></section>'
EXTRA={'de':[('clock','Du weißt, wann du ankommst.','Nach etwa 15 Minuten richtet sich die Ankunftszeit nach deinem Tempo – bergauf, flach und bergab getrennt.'),('vibrate','Das Handy lenkt nicht ab.','Zu Fuß bleibt es in der Tasche: Wo du falsch abbiegen könntest, vibriert es – einmal für links, zweimal für rechts. Am Lenker zeigt es nur Pfeil, Entfernung und Ankunft auf schwarzem Grund – die Karte erscheint erst kurz vor der Abbiegung.'),('cable','Mit Seilbahn oder Bus? Die Tour stimmt trotzdem.','Fahrten werden erkannt. Am Ende nimmst du sie mit einem Tipp aus Strecke und Zeit heraus.')],
'en':[('clock','You know when you will arrive.','After about 15 minutes the arrival time follows your pace – uphill, flat and downhill separately.'),('vibrate','Your phone does not distract you.','On foot it stays in your pocket: where you could take the wrong way, it vibrates – once for left, twice for right. On the handlebar it shows only an arrow, distance and arrival on a black screen – the map appears shortly before the turn.'),('cable','Cable car or bus? The tour still adds up.','Rides are recognised. At the end, one tap leaves them out of distance and time.')]}
SMALL={'de':dict(eye='Im Alltag durchdacht',h='Kleine Details.<br>Große Ruhe unterwegs.',cols=[('Unterwegs',[('Nichts wird ohne Frage umgeplant.','Kommst du vom Weg ab, vibriert das Handy und fragt. Die alte Route bleibt grau sichtbar.'),('Beim Navigieren geschützt.','Beim Navigieren reagiert die Karte nicht auf Berührung. Zum Ändern schiebst du einen Schalter.'),('Speichern ohne viele Fragen.','Tour beenden ist ein Tipp. Den Namen schlägt OnPath vor – nach den Orten, durch die du gekommen bist.'),('Unterwegs umplanen.','Ändere dein Ziel oder ergänze einen Stopp. Deine Aufzeichnung läuft weiter, bereits besuchte Punkte werden übersprungen.'),('Jeder Punkt wird sofort gespeichert.','Die Aufzeichnung endet nur, wenn du sie beendest. Nach einem Neustart des Handys setzt du sie mit einem Tipp fort.')]),('Beim Planen',[('Ehrlich, wenn es nicht geht.','Ist ein Ziel mit deiner Aktivität nicht erreichbar, zeigt OnPath die Lücke – statt heimlich einen Umweg zu nehmen.'),('Die Karte zeigt, was für dich geht.','Wege in Grün, Schwarz, Grau oder Rot – je nachdem, ob sie für deine Aktivität passen.'),('Wandern nach SAC-Skala.','T1 bis T5: Wege über deiner Stufe und Klettersteige lässt OnPath aus – soweit sie in der Karte eingetragen sind.'),('Adressen auch ohne Netz.','Straße mit Hausnummer, Dorf, Hütte oder Gipfel – gefunden direkt auf dem Handy.')])],link=('/hilfe/','Alles Schritt für Schritt in der Hilfe')),
'en':dict(eye='Thoughtful in everyday use',h='Small details.<br>Peace of mind on the way.',cols=[('On the way',[('Nothing is re-routed without asking.','If you leave the route, the phone vibrates and asks. The old route stays visible in grey.'),('Protected while navigating.','While navigating, touching the map does nothing. To edit, you slide a switch.'),('Saving without a lot of questions.','Ending a tour is one tap. OnPath suggests the name from the places you passed.'),('Change the plan along the way.','Change your destination or add a stop. Your recording keeps running and points already visited are skipped.'),('Every point is saved at once.','A recording ends only when you end it. After a phone restart you continue it with one tap.')]),('When planning',[('Honest when it does not work.','If a destination cannot be reached with your activity, OnPath shows the gap instead of quietly making a detour.'),('The map shows what works for you.','Ways in green, black, grey or red – depending on whether they suit your activity.'),('Hiking by SAC scale.','T1 to T5: trails above your level and via ferratas are left out – as far as the map records them.'),('Addresses without signal.','Street and house number, village, hut or peak – found right on the phone.')])],link=('/help/','Everything step by step in the help'))}
